const MS_PER_HOUR = 60 * 60 * 1000;
const MS_PER_DAY = 24 * MS_PER_HOUR;

/** Lifetime of a sign-in that did not ask to be remembered. */
const SESSION_TTL_MS = 24 * MS_PER_HOUR;
/** Lifetime of a sign-in made with "remember me". */
const REMEMBERED_SESSION_TTL_MS = 30 * MS_PER_DAY;

/** Length in bytes of the raw session token handed to the browser. */
const TOKEN_BYTES = 32;

/**
 * Mints a session. Only the hash reaches the database, so a dump of the
 * `sessions` table cannot be replayed as a login. `rememberMe` picks between
 * the short and the long lifetime.
 */
export async function createSessionToken(
  userId: UserId,
  rememberMe = false,
): Promise<{ token: string; expiresAt: IsoTimestamp }> {
  const token = randomToken(TOKEN_BYTES);
  const ttl = rememberMe ? REMEMBERED_SESSION_TTL_MS : SESSION_TTL_MS;
  const expiresAt = toIsoTimestamp(new Date(Date.now() + ttl));

